<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>FreelaHub - Marketplace de Serviços Freelance</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link rel="stylesheet" href="/styles.css">
</head>
<body class="text-slate-800 min-h-screen flex flex-col antialiased">

  <!-- ================= NAVBAR ================= -->
  <header class="bg-white border-b border-slate-200 sticky top-0 z-40 shadow-sm">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">

      <!-- Logo -->
      <div class="flex items-center space-x-3 cursor-pointer" onclick="navegarPara('marketplace')">
        <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-blue-500 flex items-center justify-center text-white font-black text-xl shadow-md shadow-indigo-100">
          F
        </div>
        <div>
          <span class="text-xl font-extrabold text-slate-900 tracking-tight">Freela<span class="text-indigo-600">Hub</span></span>
          <span class="hidden sm:inline-block ml-2 text-xs font-semibold px-2 py-0.5 bg-indigo-50 text-indigo-700 rounded-full">Mercado Aberto</span>
        </div>
      </div>

      <!-- Links de Navegação Central -->
      <nav class="hidden md:flex items-center space-x-1 text-sm font-medium">
        <button onclick="navegarPara('marketplace')" id="nav-btn-marketplace" class="px-3 py-2 rounded-lg text-indigo-600 bg-indigo-50 font-semibold transition">
          Explorar Serviços
        </button>
        <button onclick="navegarPara('meus-servicos')" id="nav-btn-meus-servicos" class="px-3 py-2 rounded-lg text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition auth-obrigatoria hidden">
          Meus Serviços
        </button>
        <button onclick="navegarPara('meus-contratos')" id="nav-btn-meus-contratos" class="px-3 py-2 rounded-lg text-slate-600 hover:text-slate-900 hover:bg-slate-100 transition auth-obrigatoria hidden">
          Meus Contratos
        </button>
        <button onclick="navegarPara('admin')" id="nav-btn-admin" class="px-3 py-2 rounded-lg text-amber-700 hover:bg-amber-50 font-semibold transition admin-obrigatorio hidden">
          🛡️ Painel Admin
        </button>
      </nav>

      <!-- Ações de Usuário -->
      <div class="flex items-center space-x-3">
        <div id="area-deslogado" class="flex items-center space-x-2">
          <button onclick="abrirModalAuth('login')" class="text-sm font-semibold text-slate-700 hover:text-indigo-600 px-3 py-2 rounded-lg transition">
            Entrar
          </button>
          <button onclick="abrirModalAuth('cadastro')" class="text-sm font-semibold bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg shadow-sm shadow-indigo-200 transition">
            Criar Conta
          </button>
        </div>

        <div id="area-logado" class="hidden flex items-center space-x-3">
          <button onclick="abrirModalNovoServico()" class="hidden sm:inline-flex items-center text-sm font-semibold bg-slate-900 hover:bg-black text-white px-3.5 py-2 rounded-lg transition">
            + Publicar Serviço
          </button>
          <div class="relative">
            <button onclick="toggleMenuUsuario()" class="flex items-center space-x-2 p-1.5 rounded-xl border border-slate-200 hover:border-slate-300 bg-white text-left transition">
              <div class="w-8 h-8 rounded-lg bg-indigo-100 text-indigo-700 font-bold flex items-center justify-center text-xs" id="user-avatar-letra">
                U
              </div>
              <span class="text-xs font-semibold text-slate-700 max-w-[100px] truncate" id="user-display-nome">Usuário</span>
              <svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>
            </button>

            <!-- Dropdown Menu -->
            <div id="dropdown-usuario" class="hidden absolute right-0 mt-2 w-52 bg-white rounded-xl shadow-xl border border-slate-100 py-1.5 z-50 fade-in">
              <div class="px-3 py-2 border-b border-slate-100">
                <p class="text-xs font-semibold text-slate-900 truncate" id="menu-user-nome">Nome</p>
                <p class="text-[11px] text-slate-500 truncate" id="menu-user-email">email@exemplo.com</p>
                <span id="menu-user-badge" class="inline-block mt-1 text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-slate-100 text-slate-600">Usuário</span>
              </div>
              <button onclick="navegarPara('marketplace'); toggleMenuUsuario();" class="w-full text-left px-3 py-2 text-xs text-slate-700 hover:bg-slate-50 md:hidden font-medium">Explorar Serviços</button>
              <button onclick="navegarPara('meus-servicos'); toggleMenuUsuario();" class="w-full text-left px-3 py-2 text-xs text-slate-700 hover:bg-slate-50 font-medium">Meus Serviços Cadastrados</button>
              <button onclick="navegarPara('meus-contratos'); toggleMenuUsuario();" class="w-full text-left px-3 py-2 text-xs text-slate-700 hover:bg-slate-50 font-medium">Meus Contratos e Pedidos</button>
              <button onclick="navegarPara('admin'); toggleMenuUsuario();" class="w-full text-left px-3 py-2 text-xs text-amber-700 hover:bg-amber-50 font-semibold admin-obrigatorio hidden">🛡️ Painel Administrador</button>
              <div class="border-t border-slate-100 my-1"></div>
              <button onclick="fazerLogout()" class="w-full text-left px-3 py-2 text-xs text-rose-600 hover:bg-rose-50 font-semibold">Sair da Conta</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </header>

  <!-- ================= NOTIFICAÇÃO TOAST ================= -->
  <div id="toast" class="fixed bottom-5 right-5 z-50 transform transition-all duration-300 translate-y-24 opacity-0 pointer-events-none">
    <div id="toast-cor" class="flex items-center space-x-3 px-4 py-3 rounded-xl shadow-lg border text-sm font-medium">
      <span id="toast-icone">✓</span>
      <span id="toast-mensagem">Mensagem de alerta</span>
    </div>
  </div>

  <!-- ================= CONTEÚDO PRINCIPAL ================= -->
  <main class="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">

    <!-- SEÇÃO 1: MARKETPLACE GERAL -->
    <section id="view-marketplace" class="space-y-8 fade-in">
      <!-- Banner Hero -->
      <div class="bg-gradient-to-r from-slate-900 via-indigo-950 to-slate-900 rounded-3xl p-8 sm:p-12 text-white shadow-xl relative overflow-hidden">
        <div class="relative z-10 max-w-2xl space-y-4">
          <span class="inline-block text-xs font-bold uppercase tracking-wider bg-indigo-500/20 text-indigo-300 border border-indigo-400/30 px-3 py-1 rounded-full">
            Marketplace Seguro & Direto
          </span>
          <h1 class="text-3xl sm:text-4xl font-extrabold tracking-tight leading-tight">
            Encontre freelancers qualificados ou ofereça o seu trabalho.
          </h1>
          <p class="text-slate-300 text-sm sm:text-base leading-relaxed">
            Sem burocracia: publique seus talentos, contrate profissionais verificados e faça tudo funcionar de qualquer computador ou celular.
          </p>
          <div class="pt-2 flex flex-wrap gap-3">
            <button onclick="abrirModalNovoServico()" class="bg-indigo-600 hover:bg-indigo-500 text-white font-semibold text-sm px-5 py-3 rounded-xl shadow-lg transition">
              + Oferecer Meu Serviço
            </button>
          </div>
        </div>
      </div>

      <!-- Filtros e Busca -->
      <div class="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-sm flex flex-col md:flex-row gap-4 items-center justify-between">
        <div class="relative w-full md:w-96">
          <input type="text" id="filtro-busca" placeholder="O que você precisa hoje? (ex: logo, site, texto...)"
            oninput="filtrarServicos()"
            class="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500">
          <svg class="w-5 h-5 text-slate-400 absolute left-3 top-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
          </svg>
        </div>

        <div class="flex items-center space-x-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0">
          <button onclick="selecionarCategoria('todas')" class="btn-categoria active px-4 py-2 rounded-xl text-xs font-semibold whitespace-nowrap bg-indigo-600 text-white transition">Todas</button>
          <button onclick="selecionarCategoria('Design')" class="btn-categoria px-4 py-2 rounded-xl text-xs font-semibold whitespace-nowrap bg-slate-100 text-slate-600 hover:bg-slate-200 transition">Design</button>
          <button onclick="selecionarCategoria('Programação')" class="btn-categoria px-4 py-2 rounded-xl text-xs font-semibold whitespace-nowrap bg-slate-100 text-slate-600 hover:bg-slate-200 transition">Programação</button>
          <button onclick="selecionarCategoria('Redação & Tradução')" class="btn-categoria px-4 py-2 rounded-xl text-xs font-semibold whitespace-nowrap bg-slate-100 text-slate-600 hover:bg-slate-200 transition">Redação & Tradução</button>
          <button onclick="selecionarCategoria('Marketing')" class="btn-categoria px-4 py-2 rounded-xl text-xs font-semibold whitespace-nowrap bg-slate-100 text-slate-600 hover:bg-slate-200 transition">Marketing</button>
          <button onclick="selecionarCategoria('Outros')" class="btn-categoria px-4 py-2 rounded-xl text-xs font-semibold whitespace-nowrap bg-slate-100 text-slate-600 hover:bg-slate-200 transition">Outros</button>
        </div>
      </div>

      <!-- Grid de Serviços -->
      <div id="grid-servicos" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        <!-- Renderizado dinamicamente pelo JavaScript -->
      </div>
    </section>

    <!-- SEÇÃO 2: MEUS SERVIÇOS (PRESTADOR) -->
    <section id="view-meus-servicos" class="hidden space-y-6 fade-in">
      <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-200 pb-5">
        <div>
          <h2 class="text-2xl font-bold text-slate-900">Meus Serviços Cadastrados</h2>
          <p class="text-sm text-slate-500">Gerencie os serviços que você oferece para outras pessoas contratarem.</p>
        </div>
        <button onclick="abrirModalNovoServico()" class="bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-semibold px-4 py-2.5 rounded-xl shadow-sm transition">
          + Criar Novo Serviço
        </button>
      </div>

      <div id="lista-meus-servicos" class="grid grid-cols-1 md:grid-cols-2 gap-4">
        <!-- Renderizado via JS -->
      </div>
    </section>

    <!-- SEÇÃO 3: MEUS CONTRATOS (CLIENTE & PRESTADOR) -->
    <section id="view-meus-contratos" class="hidden space-y-8 fade-in">
      <div class="border-b border-slate-200 pb-5">
        <h2 class="text-2xl font-bold text-slate-900">Contratos & Pedidos</h2>
        <p class="text-sm text-slate-500">Acompanhe os serviços que você contratou de terceiros e os trabalhos que solicitaram a você.</p>
      </div>

      <!-- Tabs de Contratos -->
      <div class="flex space-x-3 border-b border-slate-200">
        <button onclick="alternarTabContrato('contratados')" id="tab-contratados-btn" class="pb-3 text-sm font-bold border-b-2 border-indigo-600 text-indigo-600 transition">
          Serviços que Contratei
        </button>
        <button onclick="alternarTabContrato('trabalhos')" id="tab-trabalhos-btn" class="pb-3 text-sm font-bold border-b-2 border-transparent text-slate-500 hover:text-slate-800 transition">
          Trabalhos a Realizar (Meus Pedidos)
        </button>
      </div>

      <!-- Conteúdo da tab Contratados por Mim -->
      <div id="tab-conteudo-contratados" class="space-y-4">
        <div id="lista-contratados" class="space-y-3">
          <!-- Renderizado via JS -->
        </div>
      </div>

      <!-- Conteúdo da tab Meus Trabalhos como Prestador -->
      <div id="tab-conteudo-trabalhos" class="hidden space-y-4">
        <div id="lista-trabalhos" class="space-y-3">
          <!-- Renderizado via JS -->
        </div>
      </div>
    </section>

    <!-- SEÇÃO 4: PAINEL DO ADMINISTRADOR -->
    <section id="view-admin" class="hidden space-y-8 fade-in">
      <div class="bg-amber-500/10 border border-amber-500/20 rounded-2xl p-6">
        <div class="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <span class="inline-block text-xs font-extrabold uppercase tracking-wide bg-amber-600 text-white px-2.5 py-0.5 rounded-full mb-1">Área Administrativa</span>
            <h2 class="text-2xl font-black text-slate-900">Central de Moderação & Gestão</h2>
            <p class="text-xs sm:text-sm text-slate-600">Aprove ou rejeite serviços, suspenda usuários e audite todos os contratos do marketplace.</p>
          </div>
          <div class="grid grid-cols-2 sm:grid-cols-4 gap-3" id="admin-cards-estatisticas">
            <!-- Estatísticas dinâmicas -->
          </div>
        </div>
      </div>

      <!-- Navegação Interna do Admin -->
      <div class="flex border-b border-slate-200 space-x-4">
        <button onclick="alternarSubTabAdmin('servicos')" id="adm-tab-servicos" class="pb-3 text-sm font-bold border-b-2 border-amber-600 text-amber-700">
          Moderação de Serviços
        </button>
        <button onclick="alternarSubTabAdmin('usuarios')" id="adm-tab-usuarios" class="pb-3 text-sm font-bold border-b-2 border-transparent text-slate-500 hover:text-slate-900">
          Gerenciar Usuários
        </button>
        <button onclick="alternarSubTabAdmin('contratos')" id="adm-tab-contratos" class="pb-3 text-sm font-bold border-b-2 border-transparent text-slate-500 hover:text-slate-900">
          Todos os Contratos
        </button>
      </div>

      <!-- Admin: Serviços -->
      <div id="adm-painel-servicos" class="space-y-4">
        <div class="overflow-x-auto bg-white rounded-2xl border border-slate-200 shadow-sm">
          <table class="w-full text-left text-sm text-slate-600">
            <thead class="bg-slate-50 text-xs uppercase font-semibold text-slate-500 border-b border-slate-200">
              <tr>
                <th class="px-5 py-3.5">Serviço</th>
                <th class="px-5 py-3.5">Prestador</th>
                <th class="px-5 py-3.5">Preço</th>
                <th class="px-5 py-3.5">Status Atual</th>
                <th class="px-5 py-3.5 text-right">Ações de Moderação</th>
              </tr>
            </thead>
            <tbody id="adm-tabela-servicos" class="divide-y divide-slate-100">
              <!-- Renderizado via JS -->
            </tbody>
          </table>
        </div>
      </div>

      <!-- Admin: Usuários -->
      <div id="adm-painel-usuarios" class="hidden space-y-4">
        <div class="overflow-x-auto bg-white rounded-2xl border border-slate-200 shadow-sm">
          <table class="w-full text-left text-sm text-slate-600">
            <thead class="bg-slate-50 text-xs uppercase font-semibold text-slate-500 border-b border-slate-200">
              <tr>
                <th class="px-5 py-3.5">Usuário</th>
                <th class="px-5 py-3.5">Contato</th>
                <th class="px-5 py-3.5">Papel</th>
                <th class="px-5 py-3.5">Status</th>
                <th class="px-5 py-3.5 text-right">Ações</th>
              </tr>
            </thead>
            <tbody id="adm-tabela-usuarios" class="divide-y divide-slate-100">
              <!-- Renderizado via JS -->
            </tbody>
          </table>
        </div>
      </div>

      <!-- Admin: Todos os Contratos -->
      <div id="adm-painel-contratos" class="hidden space-y-4">
        <div class="overflow-x-auto bg-white rounded-2xl border border-slate-200 shadow-sm">
          <table class="w-full text-left text-sm text-slate-600">
            <thead class="bg-slate-50 text-xs uppercase font-semibold text-slate-500 border-b border-slate-200">
              <tr>
                <th class="px-5 py-3.5">ID / Data</th>
                <th class="px-5 py-3.5">Serviço</th>
                <th class="px-5 py-3.5">Contratante</th>
                <th class="px-5 py-3.5">Prestador</th>
                <th class="px-5 py-3.5">Valor</th>
                <th class="px-5 py-3.5">Status</th>
              </tr>
            </thead>
            <tbody id="adm-tabela-contratos" class="divide-y divide-slate-100">
              <!-- Renderizado via JS -->
            </tbody>
          </table>
        </div>
      </div>
    </section>

  </main>

  <!-- ================= MODAIS ================= -->

  <!-- Modal de Autenticação (Login / Cadastro) -->
  <div id="modal-auth" class="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 hidden">
    <div class="bg-white rounded-3xl max-w-md w-full p-6 sm:p-8 shadow-2xl relative fade-in">
      <button onclick="fecharModalAuth()" class="absolute top-5 right-5 text-slate-400 hover:text-slate-600 text-xl font-bold">×</button>

      <div class="text-center mb-6">
        <h3 id="auth-titulo" class="text-2xl font-bold text-slate-900">Bem-vindo ao FreelaHub</h3>
        <p id="auth-subtitulo" class="text-sm text-slate-500 mt-1">Acesse sua conta para continuar</p>
      </div>

      <form id="form-auth" onsubmit="enviarAutenticacao(event)" class="space-y-4">
        <div id="campo-auth-nome" class="hidden space-y-1">
          <label class="text-xs font-bold text-slate-700">Seu Nome Completo</label>
          <input type="text" id="auth-nome" placeholder="Ex: Ana Silva" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500">
        </div>

        <div class="space-y-1">
          <label class="text-xs font-bold text-slate-700">E-mail</label>
          <input type="email" id="auth-email" required placeholder="seu@email.com" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500">
        </div>

        <div class="space-y-1">
          <label class="text-xs font-bold text-slate-700">Senha</label>
          <input type="password" id="auth-senha" required placeholder="••••••••" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500">
        </div>

        <div id="campos-auth-extras" class="hidden space-y-4">
          <div class="space-y-1">
            <label class="text-xs font-bold text-slate-700">Telefone / WhatsApp (Opcional)</label>
            <input type="text" id="auth-telefone" placeholder="(11) 99999-9999" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500">
          </div>
          <div class="space-y-1">
            <label class="text-xs font-bold text-slate-700">Apresentação rápida / Bio</label>
            <textarea id="auth-bio" rows="2" placeholder="Ex: Sou redator freelancer há 3 anos..." class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"></textarea>
          </div>
        </div>

        <button type="submit" id="auth-btn-submit" class="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold text-sm shadow-md shadow-indigo-100 transition mt-2">
          Entrar na Conta
        </button>
      </form>

      <div class="mt-6 pt-4 border-t border-slate-100 text-center text-xs text-slate-500">
        <span id="auth-toggle-texto">Não possui uma conta?</span>
        <button type="button" onclick="alternarModoAuth()" id="auth-toggle-btn" class="font-bold text-indigo-600 hover:underline ml-1">
          Cadastre-se grátis
        </button>
      </div>
    </div>
  </div>

  <!-- Modal: Publicar Novo Serviço -->
  <div id="modal-novo-servico" class="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 hidden">
    <div class="bg-white rounded-3xl max-w-lg w-full p-6 sm:p-8 shadow-2xl relative max-h-[90vh] overflow-y-auto fade-in">
      <button onclick="fecharModalNovoServico()" class="absolute top-5 right-5 text-slate-400 hover:text-slate-600 text-xl font-bold">×</button>

      <div class="mb-6">
        <h3 class="text-xl font-bold text-slate-900">Publicar Novo Serviço</h3>
        <p class="text-xs text-slate-500 mt-0.5">Seu serviço passará pela aprovação do administrador para garantir a segurança da plataforma.</p>
      </div>

      <form id="form-novo-servico" onsubmit="enviarNovoServico(event)" class="space-y-4">
        <div>
          <label class="block text-xs font-bold text-slate-700 mb-1">Título do Serviço</label>
          <input type="text" id="servico-titulo" required placeholder="Ex: Desenvolvo logotipo para sua empresa" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500">
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Categoria</label>
            <select id="servico-categoria" required class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-white">
              <option value="Design">Design</option>
              <option value="Programação">Programação</option>
              <option value="Redação & Tradução">Redação & Tradução</option>
              <option value="Marketing">Marketing</option>
              <option value="Outros">Outros</option>
            </select>
          </div>

          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">Preço Cobrado (R$)</label>
            <input type="number" id="servico-preco" step="0.01" min="10" required placeholder="150.00" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500">
          </div>
        </div>

        <div>
          <label class="block text-xs font-bold text-slate-700 mb-1">Prazo de Entrega Estimado (dias)</label>
          <input type="number" id="servico-prazo" min="1" required placeholder="Ex: 3" class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500">
        </div>

        <div>
          <label class="block text-xs font-bold text-slate-700 mb-1">Descrição Completa</label>
